ALTER TABLE orders SET (
    autovacuum_vacuum_scale_factor = 0.05,
    autovacuum_vacuum_cost_limit = 2000
);

// Atomic Sliding Window Rate Limiter via ZSET:
long now = System.currentTimeMillis();
jedis.zadd("rate:" + userId, now, String.valueOf(now));
jedis.zremrangeByScore("rate:" + userId, 0, now - 60000);
long count = jedis.zcard("rate:" + userId);

String cachedUser = redisTemplate.opsForValue().get("user:" + id);
if (cachedUser == null) {
    User user = userRepo.findById(id);
    redisTemplate.opsForValue().set("user:" + id, json(user), 10, TimeUnit.MINUTES);
}

